    comp: [{ mots: ["Mola", "gourma", "Tem", "sept"], texte: "Au XVIIIe siècle, les {a}, venus du pays {b}, s'unissent aux {c} déjà installés et fondent les chefferies. Le pouvoir tourne entre les {d} chefferies du royaume." }],
    classer: [{ consigne: "Classe ces éléments selon le peuple qui les a apportés au Tchaoudjo.", cats: ["Mola", "Mandé"], elts: [["la chefferie", 0], ["l'islam", 1], ["la circoncision", 1], ["la cavalerie", 1], ["le boubou", 1], ["la cordonnerie", 1]] }],
    cours: [["Quels peuples ont formé la société du Tchaoudjo ?", 1.5, "Les Tem, les plus anciens (0,5 pt) ; les Mola, venus du pays gourma (0,5 pt) ; les Mandé (0,5 pt)."], ["Comment le pouvoir était-il exercé au Tchaoudjo avant Ouro Djobo Boukari ?", 1, "Il tournait entre les sept chefferies (0,5 pt), Kpangalam la première (0,5 pt)."], ["Quelle place la religion tient-elle au Tchaoudjo ?", 1, "L'islam domine dans les villes (0,5 pt) ; la religion traditionnelle reste forte dans les villages (0,5 pt)."], ["Qui entourait le roi du Tchaoudjo ?", 1, "Des notables (0,5 pt) et, après sa conversion, des dignitaires musulmans comme l'imam (0,5 pt)."], ["Qui étaient les sémassi et à quoi ont-ils servi ?", 1, "Les cavaliers musulmans d'Ouro Djobo Boukari (0,5 pt) ; ils l'ont aidé à soumettre ses opposants et ses voisins, comme les Anyanga (0,5 pt)."], ["Cite trois cultures pratiquées au Tchaoudjo.", 1.5, "Le mil, l'igname, le coton (0,5 pt chacun)."], ["Pourquoi dit-on que le Tchaoudjo a été un royaume commerçant ?", 1, "Les Tem sont de grands commerçants (0,5 pt) et le Tchaoudjo était une étape sur les routes de la kola (0,5 pt)."]]
